<?php\nrequire 'db_connect.php';\n\n// Script para criar a tabela de reservas se não existir\n$sql = \"CREATE TABLE IF NOT EXISTS reservas (\n    id VARCHAR(50) PRIMARY KEY,\n    user_id INT NOT NULL,\n    data DATE NOT NULL,\n    valor DECIMAL(10, 2) NOT NULL,\n    status ENUM('pendente', 'confirmado', 'cancelado') DEFAULT 'pendente',\n    observacoes TEXT,\n    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,\n    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,\n    FOREIGN KEY (user_id) REFERENCES usuarios(id) ON DELETE CASCADE\n)\";\n\nif ($conn->query($sql) === TRUE) {\n    echo \"Tabela 'reservas' está pronta para uso!\";\n} else {\n    echo \"Erro ao criar tabela: \" . $conn->error;\n}\n\n// Adicionar coluna status à tabela agenda se não existir\n$checkColumn = \"SHOW COLUMNS FROM agenda LIKE 'status'\";\n$result = $conn->query($checkColumn);\n\nif ($result->num_rows == 0) {\n    $addColumn = \"ALTER TABLE agenda ADD COLUMN status ENUM('ativo', 'reservado', 'pendente') DEFAULT 'ativo'\";\n    if ($conn->query($addColumn) === TRUE) {\n        echo \"\\nColuna 'status' adicionada à tabela 'agenda'.\";\n    } else {\n        echo \"\\nErro ao adicionar coluna 'status': \" . $conn->error;\n    }\n} else {\n    echo \"\\nColuna 'status' já existe na tabela 'agenda'.\";\n}\n\n$conn->close();\n?>